function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
module.exports=(req,res)=>{
 try{
  const d=typeof req.body==='string'?JSON.parse(req.body):req.body;
  const rows=[...(d.rows||[])].sort((a,b)=>(Number(b.gp)-Number(a.gp))||String(a.player).localeCompare(String(b.player),undefined,{sensitivity:'base'}));
  const best=(k,low=false)=>[...rows].sort((a,b)=>low?Number(a[k])-Number(b[k]):Number(b[k])-Number(a[k]))[0]||{};
  const leaders=[['POINTS',best('pts'),'pts'],['REBOUNDS',best('reb'),'reb'],['ASSISTS',best('ast'),'ast'],['STEALS + BLOCKS',best('stocks'),'stocks'],['LOWEST TURNOVERS',best('to',true),'to']];
  const navy='#07305c',blue='#1d2d77',gold='#bd850a',cream='#faf8ef',grid='#9eacb5';
  let trs=rows.map((r,i)=>{const y=253+i*55;const vals=[r.player,r.gp,r.wl,r.pts,r.reb,r.ast,r.to,r.stocks];const xs=[48,244,356,472,588,703,818,938];return `<g>${vals.map((v,j)=>`<text x="${xs[j]}" y="${y+35}" font-size="24" font-weight="700" fill="${blue}" text-anchor="${j?'middle':'start'}">${esc(v)}</text>`).join('')}<line x1="28" y1="${y+54}" x2="1012" y2="${y+54}" stroke="${grid}"/></g>`}).join('');
  let leaderSvg=leaders.map(([label,r,k],i)=>{const y=265+i*132;return `<g><circle cx="1082" cy="${y+61}" r="39" fill="none" stroke="${blue}" stroke-width="2"/><text x="1082" y="${y+78}" text-anchor="middle" font-family="Georgia" font-size="46" font-weight="900" fill="${navy}">Y</text><text x="1250" y="${y+25}" text-anchor="middle" font-size="17" font-weight="800" fill="${blue}">${label}</text><text x="1250" y="${y+76}" text-anchor="middle" font-size="50" font-weight="900" fill="${gold}">${esc(r[k]??'')}</text><text x="1250" y="${y+105}" text-anchor="middle" font-size="20" font-weight="900" fill="${blue}">${esc(String(r.player||'').toUpperCase())}</text>${i<4?`<line x1="1035" y1="${y+130}" x2="1365" y2="${y+130}" stroke="${grid}"/>`:''}</g>`}).join('');
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1408" height="1056" viewBox="0 0 1408 1056"><rect width="1408" height="1056" fill="${cream}"/><rect x="3" y="3" width="1402" height="1050" fill="none" stroke="${gold}" stroke-width="3"/><rect x="12" y="12" width="1384" height="1032" fill="none" stroke="${gold}"/><text x="210" y="112" font-family="Georgia" font-size="88" font-weight="900" fill="${navy}">Y</text><text x="704" y="108" text-anchor="middle" font-family="Georgia" font-size="72" font-weight="700" letter-spacing="3" fill="${navy}">DAILY STATS</text><line x1="193" y1="150" x2="1215" y2="150" stroke="#b9c3c9"/><g font-family="Arial" font-size="23" font-weight="900" fill="${blue}"><text x="300" y="190">SEASON ${esc(d.season)}</text><text x="520" y="190">WEEK ${esc(d.week)}</text><text x="700" y="190">${esc(String(d.date||'').toUpperCase())}</text><text x="1110" y="190">${esc(String(d.day||'').toUpperCase())}</text></g><rect x="28" y="206" width="984" height="47" fill="${navy}"/><g font-family="Arial" font-size="20" font-weight="900" fill="${gold}" text-anchor="middle"><text x="107" y="237">PLAYER</text><text x="244" y="237">GP</text><text x="356" y="237">W-L</text><text x="472" y="237">PTS</text><text x="588" y="237">REB</text><text x="703" y="237">AST</text><text x="818" y="237">TO</text><text x="944" y="237">STL+BLK</text></g><g font-family="Arial">${trs}</g><rect x="1026" y="206" width="354" height="707" rx="12" fill="none" stroke="${navy}" stroke-width="2"/><path d="M1038 206h330a12 12 0 0 1 12 12v34h-354v-34a12 12 0 0 1 12-12" fill="${navy}"/><text x="1203" y="237" text-anchor="middle" font-family="Arial" font-size="22" font-weight="900" fill="${gold}">★  TOP PLAYERS  ★</text><g font-family="Arial">${leaderSvg}</g><text x="704" y="1022" text-anchor="middle" font-family="Georgia" font-size="16" font-weight="800" fill="${blue}">Y’S GUYS OFFICIAL STATISTICAL REPORT</text></svg>`;
  res.setHeader('Content-Type','image/svg+xml; charset=utf-8');res.setHeader('Content-Disposition',`attachment; filename="ys-guys-daily-stats-week-${esc(d.week)}.svg"`);res.status(200).send(svg);
 }catch(e){res.status(400).json({error:e.message});}
};